CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('personal','clinic')),name text NOT NULL,slug text NOT NULL UNIQUE,timezone text NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE principals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),name text NOT NULL,email text NOT NULL,password_hash text,status text NOT NULL CHECK(status IN ('pending','active','disabled')),title text NOT NULL DEFAULT '',is_owner boolean NOT NULL DEFAULT false,auth_version integer NOT NULL DEFAULT 1,UNIQUE(account_id,email),UNIQUE(account_id,id));
CREATE UNIQUE INDEX one_owner ON principals(account_id) WHERE is_owner;
CREATE TABLE capability_grants(account_id uuid NOT NULL,principal_id uuid NOT NULL,capability text NOT NULL,PRIMARY KEY(account_id,principal_id,capability),FOREIGN KEY(account_id,principal_id) REFERENCES principals(account_id,id));
CREATE TABLE session(sid varchar PRIMARY KEY,sess json NOT NULL,expire timestamp NOT NULL);
CREATE INDEX session_expire ON session(expire);
CREATE TABLE auth_limits(key text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE activation_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,principal_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,FOREIGN KEY(account_id,principal_id) REFERENCES principals(account_id,id));
CREATE TABLE clients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),name text NOT NULL,phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,UNIQUE(account_id,id));
CREATE TABLE patients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),client_id uuid NOT NULL,name text NOT NULL,species text NOT NULL,breed text NOT NULL DEFAULT '',sex text NOT NULL DEFAULT 'unknown',age text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,id),FOREIGN KEY(account_id,client_id) REFERENCES clients(account_id,id));
CREATE INDEX patient_search ON patients(account_id,lower(name));
CREATE TABLE visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,patient_id uuid NOT NULL,responsible_id uuid NOT NULL,state text NOT NULL DEFAULT 'waiting' CHECK(state IN ('waiting','in_consultation','ended','cancelled')),arrived_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,version integer NOT NULL DEFAULT 1,UNIQUE(account_id,id),UNIQUE(account_id,id,patient_id),FOREIGN KEY(account_id,patient_id) REFERENCES patients(account_id,id),FOREIGN KEY(account_id,responsible_id) REFERENCES principals(account_id,id));
CREATE INDEX visits_day ON visits(account_id,arrived_at);
CREATE TABLE notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,visit_id uuid NOT NULL,author_id uuid NOT NULL,content text NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','signed')),signed_at timestamptz,amends_id uuid,reason text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,id),FOREIGN KEY(account_id,visit_id) REFERENCES visits(account_id,id),FOREIGN KEY(account_id,author_id) REFERENCES principals(account_id,id),FOREIGN KEY(account_id,amends_id) REFERENCES notes(account_id,id));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,patient_id uuid,visit_id uuid,owner_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('task','follow_up')),action text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','blocked','completed','cancelled')),due_at timestamptz,reason text NOT NULL DEFAULT '',completed_at timestamptz,completed_by uuid,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,id),CHECK(visit_id IS NULL OR patient_id IS NOT NULL),FOREIGN KEY(account_id,patient_id) REFERENCES patients(account_id,id),FOREIGN KEY(account_id,visit_id,patient_id) REFERENCES visits(account_id,id,patient_id),FOREIGN KEY(account_id,owner_id) REFERENCES principals(account_id,id),FOREIGN KEY(account_id,completed_by) REFERENCES principals(account_id,id));
CREATE INDEX tasks_due ON tasks(account_id,owner_id,due_at) WHERE status NOT IN ('completed','cancelled');
CREATE TABLE handovers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,task_id uuid NOT NULL,from_id uuid NOT NULL,to_id uuid NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','accepted','declined','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,UNIQUE(account_id,id),FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id),FOREIGN KEY(account_id,from_id) REFERENCES principals(account_id,id),FOREIGN KEY(account_id,to_id) REFERENCES principals(account_id,id));
CREATE UNIQUE INDEX pending_handover ON handovers(account_id,task_id) WHERE state='pending';
CREATE TABLE contact_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL,task_id uuid NOT NULL,actor_id uuid NOT NULL,channel text NOT NULL,outcome text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id),FOREIGN KEY(account_id,actor_id) REFERENCES principals(account_id,id));
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,account_id uuid NOT NULL REFERENCES accounts(id),actor_id uuid NOT NULL,action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(account_id,actor_id) REFERENCES principals(account_id,id));
CREATE INDEX audit_account ON audit_events(account_id,id);
